-- Creating a missing Provider Account at Sweep time (#50). Generated by
-- drizzle-kit; the comments are added by hand.
--
-- An implicit Provider Account nobody funded has no key on NEAR, so the
-- delegate action of a sponsored Sweep (ADR 0010) can't land. Before the
-- wallet signs one, Herald's NEAR relayer creates the account with a little
-- NEAR, at most once (the NEAR chain queue records it too). This column is
-- the relayer transaction that created it; null for every existing row and
-- every Provider Account Herald never created.
ALTER TABLE `providers` ADD `provider_account_tx_hash` text;
